#!/usr/bin/env node
'use strict';

// docs/verify-architecture.js — AUTO-GENERATED by /document-architecture
// Re-run /document-architecture to regenerate. Manual edits will be overwritten.
//
// Checks every verifiable claim in ARCHITECTURE.md and CONTEXT.md files:
//   1. Key Constants tables: File:Line references match actual code
//   2. Scripts tables: every listed file exists on disk
//   3. Undocumented files: code files on disk not in any Scripts table
//   4. Component Map: every CONTEXT.md has a row and vice versa
//   5. Markdown links: every [text](path) points to an existing file
//
// Usage:
//   node docs/verify-architecture.js          # check all docs
//   node docs/verify-architecture.js --json   # machine-readable output
//   node docs/verify-architecture.js --fix    # (reserved for future use)
//
// Generated: 2026-04-01T00:00:00.000Z
// Covers: ARCHITECTURE.md, src/app/CONTEXT.md, src/lib/CONTEXT.md, src/components/CONTEXT.md, supabase/CONTEXT.md, content/CONTEXT.md, scripts/CONTEXT.md

var fs = require('fs');
var path = require('path');

var ROOT = path.resolve(__dirname, '..');
var args = process.argv.slice(2);
var jsonMode = args.includes('--json');
var fixMode = args.includes('--fix');

var results = { verified: 0, drifted: 0, missing: 0, undocumented: 0, errors: [] };

// --- Helpers ---

function readFile(relPath) {
  var full = path.resolve(ROOT, relPath);
  if (!fs.existsSync(full)) return null;
  return fs.readFileSync(full, 'utf8');
}

function readLine(filePath, lineNum) {
  var content = readFile(filePath);
  if (!content) return null;
  var lines = content.split('\n');
  if (lineNum < 1 || lineNum > lines.length) return null;
  return lines[lineNum - 1];
}

function log(symbol, msg) {
  if (!jsonMode) console.log(symbol + ' ' + msg);
}

// --- 1. Parse Key Constants from docs ---

function extractConstantRows(docPath) {
  var content = readFile(docPath);
  if (!content) return [];
  var rows = [];
  var lines = content.split('\n');
  var inTable = false;
  for (var i = 0; i < lines.length; i++) {
    var line = lines[i];
    // Detect Key Constants table header
    if (/Key Constants|Configuration/i.test(line) && /^##/.test(line)) {
      inTable = true;
      continue;
    }
    // End of table: next ## heading or empty section
    if (inTable && /^## /.test(line) && !/Key Constants|Configuration/i.test(line)) {
      inTable = false;
      continue;
    }
    if (!inTable) continue;
    // Parse table rows with File:Line pattern
    // Match: | name | value | `file.js:123` | or `file.js:123-456`
    var match = line.match(/\|\s*(.+?)\s*\|\s*(.+?)\s*\|\s*`([^`]+?):(\d+)(?:-\d+)?`/);
    if (match) {
      rows.push({
        doc: docPath,
        docLine: i + 1,
        name: match[1].trim(),
        value: match[2].trim(),
        file: match[3].trim(),
        line: parseInt(match[4], 10)
      });
    }
  }
  return rows;
}

function verifyConstants(docPaths) {
  log('\n\x1b[1m', '=== Key Constants Verification ===\x1b[0m');
  var allRows = [];
  for (var i = 0; i < docPaths.length; i++) {
    allRows = allRows.concat(extractConstantRows(docPaths[i]));
  }
  log('', 'Found ' + allRows.length + ' constant claims to verify.\n');

  for (var j = 0; j < allRows.length; j++) {
    var row = allRows[j];
    var filePath = row.file;
    // Resolve relative to project root
    if (!path.isAbsolute(filePath)) {
      // Handle paths like `preflight.js:356` — need to find the file
      var candidates = findFile(filePath);
      if (candidates.length === 0) {
        log('\x1b[31m✗\x1b[0m', row.name + ' — file not found: ' + filePath + ' (doc: ' + row.doc + ':' + row.docLine + ')');
        results.missing++;
        results.errors.push({ type: 'file_missing', constant: row.name, file: filePath, doc: row.doc, docLine: row.docLine });
        continue;
      }
      filePath = candidates[0];
    }

    var codeLine = readLine(filePath, row.line);
    if (codeLine === null) {
      log('\x1b[31m✗\x1b[0m', row.name + ' — line ' + row.line + ' not found in ' + filePath);
      results.missing++;
      results.errors.push({ type: 'line_missing', constant: row.name, file: filePath, line: row.line, doc: row.doc });
      continue;
    }

    // Extract the documented value — strip markdown formatting
    var cleanValue = row.value.replace(/[`*_]/g, '').trim();

    // Descriptive values (contain operators, long phrases, no leading number) are
    // not strictly verifiable against a single code line. Mark as verified if the
    // constant NAME appears on the line instead.
    var isDescriptive = /[><=&|]/.test(cleanValue) || (cleanValue.split(/\s+/).length > 4 && !/^\d/.test(cleanValue));

    var found = false;

    if (isDescriptive) {
      // For descriptive values, verify the constant/variable name appears on the line
      var constName = row.name.replace(/[()]/g, '').trim().split(/\s+/).pop();
      if (constName && codeLine.toLowerCase().includes(constName.toLowerCase())) {
        found = true;
      }
      // Also check if the first significant word of the value appears
      if (!found) {
        var firstWord = cleanValue.split(/[\s,;]+/)[0];
        if (firstWord && firstWord.length > 3 && codeLine.toLowerCase().includes(firstWord.toLowerCase())) {
          found = true;
        }
      }
    } else {
      // For concrete values, check if the number or key term appears on the line
      var numMatch = cleanValue.match(/[\d.]+/);
      if (numMatch) {
        found = codeLine.includes(numMatch[0]);
      }
      if (!found) {
        var words = cleanValue.split(/[\s,;|()]+/).filter(function(w) { return w.length > 2; });
        for (var k = 0; k < words.length; k++) {
          if (codeLine.toLowerCase().includes(words[k].toLowerCase())) {
            found = true;
            break;
          }
        }
      }
    }

    if (found) {
      log('\x1b[32m✓\x1b[0m', row.name + ' — verified at ' + row.file + ':' + row.line);
      results.verified++;
    } else {
      log('\x1b[33m⚡\x1b[0m', row.name + ' — DRIFT at ' + row.file + ':' + row.line);
      log('  ', 'Documented: ' + cleanValue);
      log('  ', 'Code line:  ' + codeLine.trim());
      results.drifted++;
      results.errors.push({ type: 'drift', constant: row.name, documented: cleanValue, actual: codeLine.trim(), file: row.file, line: row.line, doc: row.doc, docLine: row.docLine });
    }
  }
}

// --- 2. Parse Scripts tables and verify file existence ---

function extractScriptRows(docPath) {
  var content = readFile(docPath);
  if (!content) return [];
  var rows = [];
  var lines = content.split('\n');
  var inTable = false;
  var docDir = path.dirname(path.resolve(ROOT, docPath));

  for (var i = 0; i < lines.length; i++) {
    var line = lines[i];
    if (/^## (Scripts|Modules|Other Infrastructure)/i.test(line)) {
      inTable = true;
      continue;
    }
    if (inTable && /^## /.test(line) && !/Scripts|Modules|Other Infrastructure/i.test(line)) {
      inTable = false;
    }
    // Match table rows: | `filename.js` | purpose |
    if (inTable) {
      var tableMatch = line.match(/\|\s*`([^`]+\.(js|ts|py|mjs))`\s*\|/);
      if (tableMatch) {
        rows.push({ doc: docPath, file: tableMatch[1], dir: docDir });
      }
    }
    // Also match dedicated section headers: ## Script Name (`filename.js`)
    var sectionMatch = line.match(/^##[^(]*\(`([^`]+\.(js|ts|py|mjs))`\)/);
    if (sectionMatch) {
      rows.push({ doc: docPath, file: sectionMatch[1], dir: docDir });
    }
    // Also match bold inline: **`filename.js`** or (`filename.js`)
    if (!inTable) {
      var inlineMatch = line.match(/[(`]\s*`?([a-z][\w-]+\.(js|ts|py|mjs))`?\s*[)]/);
      if (inlineMatch && /^## /.test(line)) {
        rows.push({ doc: docPath, file: inlineMatch[1], dir: docDir });
      }
    }
  }
  return rows;
}

function verifyScripts(docPaths) {
  log('\n\x1b[1m', '=== Scripts Table Verification ===\x1b[0m');
  var allRows = [];
  for (var i = 0; i < docPaths.length; i++) {
    allRows = allRows.concat(extractScriptRows(docPaths[i]));
  }
  log('', 'Found ' + allRows.length + ' script references to verify.\n');

  for (var j = 0; j < allRows.length; j++) {
    var row = allRows[j];
    var fullPath = path.join(row.dir, row.file);
    if (fs.existsSync(fullPath)) {
      log('\x1b[32m✓\x1b[0m', row.file + ' exists (' + path.relative(ROOT, row.dir) + ')');
      results.verified++;
    } else {
      log('\x1b[31m✗\x1b[0m', row.file + ' MISSING from ' + path.relative(ROOT, row.dir) + ' (doc: ' + row.doc + ')');
      results.missing++;
      results.errors.push({ type: 'script_missing', file: row.file, dir: path.relative(ROOT, row.dir), doc: row.doc });
    }
  }
}

// --- 3. Undocumented files ---

function checkUndocumented(docPaths) {
  log('\n\x1b[1m', '=== Undocumented Files Check ===\x1b[0m');
  // Build set of documented files per directory
  var documented = {};
  for (var i = 0; i < docPaths.length; i++) {
    var rows = extractScriptRows(docPaths[i]);
    var docDir = path.dirname(path.resolve(ROOT, docPaths[i]));
    if (!documented[docDir]) documented[docDir] = {};
    for (var j = 0; j < rows.length; j++) {
      documented[docDir][rows[j].file] = true;
    }
  }

  // Check each documented directory for files not in any table
  var dirs = Object.keys(documented);
  var totalUndoc = 0;
  for (var d = 0; d < dirs.length; d++) {
    var dir = dirs[d];
    var files;
    try { files = fs.readdirSync(dir); } catch (e) { continue; }
    var codeFiles = files.filter(function(f) {
      return /\.(js|ts|mjs|py)$/.test(f) && !f.startsWith('.');
    });
    for (var k = 0; k < codeFiles.length; k++) {
      if (!documented[dir][codeFiles[k]]) {
        log('\x1b[33m?\x1b[0m', codeFiles[k] + ' in ' + path.relative(ROOT, dir) + ' — NOT in any Scripts table');
        totalUndoc++;
        results.undocumented++;
      }
    }
  }
  if (totalUndoc === 0) {
    log('\x1b[32m✓\x1b[0m', 'All code files are documented.');
  }
}

// --- 4. Component Map vs CONTEXT.md files ---

function verifyComponentMap() {
  log('\n\x1b[1m', '=== Component Map Verification ===\x1b[0m');
  var archContent = readFile('ARCHITECTURE.md');
  if (!archContent) {
    log('\x1b[31m✗\x1b[0m', 'ARCHITECTURE.md not found');
    results.missing++;
    return;
  }

  // Extract CONTEXT.md links from Component Map
  var mapLinks = [];
  var linkPattern = /\[`?([^`\]]+)CONTEXT\.md`?\]/g;
  var match;
  while ((match = linkPattern.exec(archContent)) !== null) {
    mapLinks.push(match[0].replace(/[`\[\]]/g, '').trim());
  }

  // Find actual CONTEXT.md files
  var contextFiles = [];
  var scriptDirs;
  try { scriptDirs = fs.readdirSync(path.join(ROOT, 'scripts')); } catch (e) { return; }
  for (var i = 0; i < scriptDirs.length; i++) {
    var ctxPath = path.join('scripts', scriptDirs[i], 'CONTEXT.md');
    if (fs.existsSync(path.join(ROOT, ctxPath))) {
      contextFiles.push(ctxPath);
    }
  }

  // Check map links → disk
  for (var j = 0; j < mapLinks.length; j++) {
    var linkPath = mapLinks[j];
    if (fs.existsSync(path.join(ROOT, linkPath))) {
      log('\x1b[32m✓\x1b[0m', 'Component Map → ' + linkPath + ' exists');
      results.verified++;
    } else {
      log('\x1b[31m✗\x1b[0m', 'Component Map → ' + linkPath + ' MISSING on disk');
      results.missing++;
    }
  }

  // Check disk → map
  for (var k = 0; k < contextFiles.length; k++) {
    var found = false;
    for (var m = 0; m < mapLinks.length; m++) {
      if (mapLinks[m].replace(/\\/g, '/').includes(contextFiles[k].replace(/\\/g, '/'))) {
        found = true;
        break;
      }
    }
    if (!found) {
      log('\x1b[33m?\x1b[0m', contextFiles[k] + ' exists but NOT in Component Map');
      results.undocumented++;
    }
  }
}

// --- 5. Markdown link verification ---

function verifyLinks(docPaths) {
  log('\n\x1b[1m', '=== Markdown Link Verification ===\x1b[0m');
  var linkPattern = /\[([^\]]+)\]\(([^)]+)\)/g;
  var checked = 0;
  var broken = 0;

  for (var i = 0; i < docPaths.length; i++) {
    var content = readFile(docPaths[i]);
    if (!content) continue;
    var docDir = path.dirname(path.resolve(ROOT, docPaths[i]));
    var match;
    while ((match = linkPattern.exec(content)) !== null) {
      var linkTarget = match[2];
      // Skip external URLs and anchors
      if (linkTarget.startsWith('http') || linkTarget.startsWith('#')) continue;
      var resolved = path.resolve(docDir, linkTarget);
      checked++;
      if (fs.existsSync(resolved)) {
        results.verified++;
      } else {
        log('\x1b[31m✗\x1b[0m', 'Broken link in ' + docPaths[i] + ': [' + match[1] + '](' + linkTarget + ')');
        broken++;
        results.missing++;
        results.errors.push({ type: 'broken_link', doc: docPaths[i], text: match[1], target: linkTarget });
      }
    }
  }
  if (broken === 0) {
    log('\x1b[32m✓\x1b[0m', checked + ' markdown links verified.');
  }
}

// --- File finder (resolves bare filenames to project paths) ---

function findFile(filename) {
  var candidates = [];
  var scriptDirs = ["src/app", "src/lib", "src/lib/cron", "src/lib/intelligence-brief", "src/lib/blog-generation", "src/lib/demand", "src/lib/auth", "src/lib/supabase", "src/lib/types", "src/components", "src/components/motion", "src/components/partner", "src/data", "supabase/functions/generate-report", "supabase/functions/evaluate-report", "scripts"];
  for (var i = 0; i < scriptDirs.length; i++) {
    var full = path.join(ROOT, scriptDirs[i], filename);
    if (fs.existsSync(full)) {
      candidates.push(path.join(scriptDirs[i], filename));
    }
  }
  // Also check project root
  if (fs.existsSync(path.join(ROOT, filename))) {
    candidates.push(filename);
  }
  return candidates;
}

// --- Main ---

function main() {
  var docPaths = ["ARCHITECTURE.md", "src/app/CONTEXT.md", "src/lib/CONTEXT.md", "src/components/CONTEXT.md", "supabase/CONTEXT.md", "content/CONTEXT.md", "scripts/CONTEXT.md"];

  if (!jsonMode) {
    console.log('\n=== Architecture Doc Verification ===');
    console.log('Project: ' + ROOT);
    console.log('Docs: ' + docPaths.length + ' files');
    console.log('Generated: 2026-04-01T00:00:00.000Z');
  }

  verifyConstants(docPaths);
  verifyScripts(docPaths);
  checkUndocumented(docPaths);
  verifyComponentMap();
  verifyLinks(docPaths);

  // Summary
  var total = results.verified + results.drifted + results.missing + results.undocumented;
  if (jsonMode) {
    console.log(JSON.stringify(results, null, 2));
  } else {
    console.log('\n=== Summary ===');
    console.log('\x1b[32m✓ ' + results.verified + ' verified\x1b[0m');
    if (results.drifted > 0) console.log('\x1b[33m⚡ ' + results.drifted + ' drifted (constants changed in code)\x1b[0m');
    if (results.missing > 0) console.log('\x1b[31m✗ ' + results.missing + ' missing (files/lines not found)\x1b[0m');
    if (results.undocumented > 0) console.log('\x1b[33m? ' + results.undocumented + ' undocumented (code files not in any table)\x1b[0m');
    console.log('Total: ' + total + ' checks');
  }

  // Exit code
  if (results.drifted > 0 || results.missing > 0) {
    process.exit(1);
  }
  process.exit(0);
}

main();
